type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "只尝试一种分组方式就放弃"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分组后只看一组的规律，忽略验证另一组"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "把分组数列当成普通等差等比来处理"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分组数列的关键是\"分开看\"。看到数列没有明显规律时，优先尝试奇偶分组。"}]}]}]}$$ AS jsonb), NULL, '数量关系-数字推理-分组数列的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "数字推理", "分组数列"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_number_reasoning_grouping", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
